export enum LoginAccountReply_Status {
  SUCCESS = 0,
  WRONG_PASSWORD = 1,
  BANNED = 2,
  REGISTERED = 3,
  ALREADY_LOGGED_IN = 4,
  UNRECOGNIZED = -1,
}

export function loginAccountReply_StatusFromJSON(object: any): LoginAccountReply_Status {
  switch (object) {
    case 0:
    case "SUCCESS":
      return LoginAccountReply_Status.SUCCESS;
    case 1:
    case "WRONG_PASSWORD":
      return LoginAccountReply_Status.WRONG_PASSWORD;
    case 2:
    case "BANNED":
      return LoginAccountReply_Status.BANNED;
    case 3:
    case "REGISTERED":
      return LoginAccountReply_Status.REGISTERED;
    case 4:
    case "ALREADY_LOGGED_IN":
      return LoginAccountReply_Status.ALREADY_LOGGED_IN;
    case -1:
    case "UNRECOGNIZED":
    default:
      return LoginAccountReply_Status.UNRECOGNIZED;
  }
}

export function loginAccountReply_StatusToJSON(object: LoginAccountReply_Status): string {
  switch (object) {
    case LoginAccountReply_Status.SUCCESS:
      return "SUCCESS";
    case LoginAccountReply_Status.WRONG_PASSWORD:
      return "WRONG_PASSWORD";
    case LoginAccountReply_Status.BANNED:
      return "BANNED";
    case LoginAccountReply_Status.REGISTERED:
      return "REGISTERED";
    case LoginAccountReply_Status.ALREADY_LOGGED_IN:
      return "ALREADY_LOGGED_IN";
    case LoginAccountReply_Status.UNRECOGNIZED:
    default:
      return "UNRECOGNIZED";
  }
}

